const asArray = (v) => (Array.isArray(v) ? v : []);
const toStr = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s ? s : null;
};
const toNum = (v) => {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(String(v).replace(",", "."));
  return Number.isFinite(n) ? n : null;
};
const normPhone = (v) => {
  const s = String(v || "").replace(/\D/g, "");
  if (!s) return null;
  if (s.length === 10) return `7${s}`;
  if (s.length === 11 && s.startsWith("8")) return `7${s.slice(1)}`;
  return s;
};

const body = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
const rawPlayers = asArray(body.players || body.items);
const players = rawPlayers
  .map((item) => {
    const p = item && typeof item === "object" ? item : {};
    return {
      clientId: toStr(p.clientId || p.id),
      phoneNorm: normPhone(p.phone || p.phoneNorm || p.phoneNumber),
      name: toStr(p.name),
      rating: toStr(p.rating || p.level || p.grade),
      ratingNumeric: toNum(p.ratingNumeric || p.numericRating || p.levelNumeric),
    };
  })
  .filter((p) => p.clientId || p.phoneNorm);

if (players.length === 0) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: "players[] is required" };
  return [null, msg, msg];
}

msg._liveRatingsCtx = { players };
msg.payload = players;
return [msg, null, msg];

msg.method = "POST";
msg.url = "https://kc.vivacrm.ru/realms/prod/protocol/openid-connect/token";
msg.headers = { "Content-Type": "application/x-www-form-urlencoded" };
msg.payload =
  "grant_type=password&client_id=React-auth-dev&username=it@citysport.pro&password=mhF-ma6-4Ju-QsJ";
return [null, msg, null];

const KEY_TOKEN = "vivacrm_access_token";
const KEY_EXPIRES_AT = "vivacrm_token_expires_at";

if (msg.statusCode !== 200 || !msg.payload?.access_token) {
  msg.statusCode = 500;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = {
    error: "Viva token error",
    details: msg.payload || null,
  };
  return [null, msg, msg];
}

const token = msg.payload.access_token;
const expiresIn = Number(msg.payload.expires_in || 300);
const players = Array.isArray(msg._liveRatingsCtx?.players) ? msg._liveRatingsCtx.players : [];

global.set(KEY_TOKEN, token);
global.set(KEY_EXPIRES_AT, Date.now() + expiresIn * 1000);

msg.vivaToken = token;
msg.payload = players;
return [msg, null, msg];

const player = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
msg._livePlayer = player;

if (!player.clientId) {
  msg.payload = {
    clientId: null,
    phoneNorm: player.phoneNorm || null,
    name: player.name || null,
    rating: player.rating || null,
    ratingNumeric:
      Number.isFinite(Number(player.ratingNumeric)) ? Number(player.ratingNumeric) : null,
    source: "NO_CLIENT_ID",
  };
  return [null, msg, msg];
}

msg.method = "GET";
msg.url = `https://api.vivacrm.ru/api/v1/clients/${encodeURIComponent(player.clientId)}`;
msg.headers = { Authorization: `Bearer ${msg.vivaToken}` };
return [msg, null, msg];

const LK_FIELD_ID = "f9790818-25fd-4b73-a781-79c02720727d";
const NUM_FIELD_ID = "eabfe27b-3f72-4496-9185-1a2ec6e6465e";

const player = msg._livePlayer || {};
const toNum = (v) => {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(String(v).replace(",", "."));
  return Number.isFinite(n) ? n : null;
};
const getField = (client, id) => {
  const list = Array.isArray(client?.customFields) ? client.customFields : [];
  const found = list.find((field) => field && field.id === id);
  const value = Array.isArray(found?.value) ? found.value[0] : null;
  return value == null ? null : String(value).trim() || null;
};

if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload !== "object") {
  msg.payload = {
    clientId: player.clientId || null,
    phoneNorm: player.phoneNorm || null,
    name: player.name || null,
    rating: player.rating || null,
    ratingNumeric: toNum(player.ratingNumeric),
    source: `FALLBACK_HTTP_${String(msg.statusCode || "ERR")}`,
  };
  return msg;
}

const client = msg.payload;
const levelLetter = getField(client, LK_FIELD_ID);
const levelNumeric = toNum(getField(client, NUM_FIELD_ID));

msg.payload = {
  clientId: player.clientId || null,
  phoneNorm: player.phoneNorm || null,
  name: player.name || null,
  rating: levelLetter || player.rating || null,
  ratingNumeric: levelNumeric ?? toNum(player.ratingNumeric),
  source: levelNumeric != null ? "VIVA_NUMERIC" : levelLetter ? "VIVA_LETTER" : "FALLBACK_EMPTY",
};
return msg;

const asArray = (v) => (Array.isArray(v) ? v : []);

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = {
  items: asArray(msg.payload),
  fetchedAt: new Date().toISOString(),
};
return [msg, msg];
